import React from 'react';
// Упрощённый стартовый экран без сторонних UI-библиотек (устойчивый рендер)

interface StartScreenProps {
  onStart: () => void;
  starting?: boolean;
}

const StartScreen: React.FC<StartScreenProps> = ({ onStart, starting = false }) => {
  // По умолчанию без картинки (устойчивее в WebView)
  const [imgOk, setImgOk] = React.useState(false);
  const collectDiag = async (): Promise<string> => {
    try {
      const w: any = window as any;
      const wa = w?.Telegram?.WebApp;
      const uid = wa?.initDataUnsafe?.user?.id || null;
      const initLen = (typeof wa?.initData === 'string' ? wa?.initData?.length : 0) || 0;
      const hasTgId = (() => { try { return !!sessionStorage.getItem('tg_id'); } catch { return false; } })();
      const token = (() => { try { return sessionStorage.getItem('token') || localStorage.getItem('token'); } catch { return null; } })();
      const tokenLen = token ? token.length : 0;
      let health = 'skip(no-tg)';
      try {
        const sid = (() => { try { return sessionStorage.getItem('tg_id'); } catch { return null; } })();
        const canPing = !!(uid || sid || initLen > 0);
        if (canPing) {
          const headers: Record<string,string> = {};
          const tgHeader = String(uid || sid || '');
          if (tgHeader) headers['X-Telegram-User-ID'] = tgHeader;
          const resp = await fetch('/api/health', { headers });
          health = resp.status + ' ' + resp.statusText;
        }
      } catch (e:any) { health = 'ERR ' + String(e?.message || e); }
      const lines = [
        '--- SoulPulse MiniApp DIAG ---',
        'ts: ' + new Date().toISOString(),
        'host: ' + (w.location && w.location.hostname),
        'isWebApp: ' + String(!!wa),
        'uid(initDataUnsafe.user.id): ' + String(uid || 'null'),
        'initData.length: ' + String(initLen),
        'session.tg_id: ' + String(hasTgId ? (sessionStorage.getItem('tg_id') || '') : 'null'),
        'token.len: ' + String(tokenLen),
        'health: ' + health,
      ];
      return lines.join('\n');
    } catch (e:any) {
      return 'diag_error: ' + String(e?.message || e);
    }
  };
  const copyAndOpenDiag = async () => {
    const text = await collectDiag();
    const fallbackCopy = (t: string) => {
      try {
        const ta = document.createElement('textarea');
        ta.value = t;
        ta.style.position = 'fixed';
        ta.style.opacity = '0';
        document.body.appendChild(ta);
        ta.select();
        document.execCommand('copy');
        document.body.removeChild(ta);
      } catch {}
    };
    try {
      if ((navigator as any).clipboard?.writeText) {
        await (navigator as any).clipboard.writeText(text).catch(() => fallbackCopy(text));
      } else {
        fallbackCopy(text);
      }
    } catch { fallbackCopy(text); }
    try {
      const blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
      const url = URL.createObjectURL(blob);
      window.open(url, '_blank');
      setTimeout(() => URL.revokeObjectURL(url), 30000);
    } catch {}
  };
  const openMiniApp = (sp?: string) => {
    try {
      const startParam = sp ? `&startapp=${encodeURIComponent(sp)}` : '&startapp=home';
      const tgLink = 'tg://resolve?domain=soulpulse_mini_bot' + startParam;
      const webLink = 'https://t.me/soulpulse_mini_bot';
      try { window.location.href = tgLink; } catch {}
      setTimeout(() => { try { window.open(webLink, '_blank'); } catch {} }, 120);
    } catch {}
  };
  return (
    <div style={{minHeight:'100dvh',display:'flex',flexDirection:'column',alignItems:'center',justifyContent:'center',padding:24}}>
      <div style={{textAlign:'center',maxWidth:420,width:'100%',background:'var(--sp-bg-card, rgba(0,0,0,0.35))',border:'1px solid var(--sp-border-primary, rgba(255,255,255,0.15))',borderRadius:16,padding:24}}>
        <div style={{marginBottom:16, display:'flex', justifyContent:'center'}}>
          {imgOk ? (
            <img src="/Soul6.png" alt="Soul" onError={() => setImgOk(false)} style={{width:120,height:120,objectFit:'contain',filter:'drop-shadow(0 6px 16px rgba(0,0,0,0.35))'}} />
          ) : (
            <div style={{fontSize:60}}>🤖</div>
          )}
        </div>
        <h3 style={{margin:0,color:'var(--sp-text-primary, #fff)'}}>Добро пожаловать в SoulPulse</h3>
        <div style={{marginTop:8,color:'var(--sp-text-secondary, #cbd5e1)'}}>Мини‑приложение готово. Нажмите «Старт», мы проверим окружение и выполним вход.</div>
        <div style={{marginTop:20, display:'flex', gap:8, justifyContent:'center', flexWrap:'wrap'}}>
          <button onClick={onStart} disabled={starting} style={{background:'#6366f1',color:'#fff',border:'none',borderRadius:8,padding:'10px 16px',cursor:'pointer'}}>
            {starting ? 'Старт…' : 'Старт'}
          </button>
          <button onClick={() => openMiniApp('home')} style={{background:'#10b981',color:'#fff',border:'none',borderRadius:8,padding:'10px 16px',cursor:'pointer'}}>
            Открыть в Telegram
          </button>
        </div>
        <div style={{marginTop:10, display:'flex', gap:8, justifyContent:'center', flexWrap:'wrap'}}>
          <button onClick={() => openMiniApp('chat')} style={{background:'#0ea5e9',color:'#fff',border:'none',borderRadius:8,padding:'8px 12px',cursor:'pointer'}}>MiniApp: Чат</button>
          <button onClick={() => openMiniApp('prompts')} style={{background:'#f59e0b',color:'#fff',border:'none',borderRadius:8,padding:'8px 12px',cursor:'pointer'}}>MiniApp: Личности</button>
          <button onClick={() => openMiniApp('all')} style={{background:'#64748b',color:'#fff',border:'none',borderRadius:8,padding:'8px 12px',cursor:'pointer'}}>MiniApp: Все страницы</button>
        </div>
        <div style={{display:'flex', justifyContent:'flex-start'}}>
          <button style={{marginTop:12, background:'transparent', color:'var(--sp-text-secondary,#cbd5e1)', border:'1px solid var(--sp-border-primary, rgba(255,255,255,0.2))', borderRadius:6, padding:'6px 10px', cursor:'pointer'}} onClick={copyAndOpenDiag}>Лог</button>
        </div>
      </div>
    </div>
  );
};

export default StartScreen;


