/**
 * 🎨 useTheme Hook
 * Хук для управления темами в SoulPulse
 */

import { useState, useEffect, useCallback } from 'react';
import { 
  ThemeName, 
  themes, 
  applyTheme, 
  getCurrentTheme, 
  getSystemTheme, 
  resolveAutoTheme,
  getAntdThemeConfig 
} from '../styles/themes';

interface UseThemeReturn {
  // Текущая тема
  currentTheme: ThemeName;
  
  // Разрешенная тема (для auto - это light или dark)
  resolvedTheme: 'light' | 'dark';
  
  // Системная тема
  systemTheme: 'light' | 'dark';
  
  // Функции управления
  setTheme: (theme: ThemeName) => void;
  toggleTheme: () => void;
  
  // Проверки
  isDark: boolean;
  isLight: boolean;
  isAuto: boolean;
  
  // Конфигурация для Ant Design
  getAntdConfig: (isMiniApp?: boolean) => any;
  
  // Доступные темы
  availableThemes: ThemeName[];
}

export const useTheme = (): UseThemeReturn => {
  const [currentTheme, setCurrentTheme] = useState<ThemeName>(() => getCurrentTheme());
  const [systemTheme, setSystemTheme] = useState<'light' | 'dark'>(() => getSystemTheme());
  
  // Разрешенная тема (для auto берем системную)
  const resolvedTheme = currentTheme === 'auto' ? systemTheme : currentTheme;
  
  // Проверки
  const isDark = resolvedTheme === 'dark';
  const isLight = resolvedTheme === 'light';
  const isAuto = currentTheme === 'auto';
  
  // Доступные темы
  const availableThemes: ThemeName[] = ['light', 'dark', 'auto'];
  
  // Применение темы
  const setTheme = useCallback((theme: ThemeName) => {
    console.log('🎨 Switching theme to:', theme);
    
    setCurrentTheme(theme);
    applyTheme(theme);
    
    // Уведомляем об изменении темы
    window.dispatchEvent(new CustomEvent('themeChange', { 
      detail: { theme, resolvedTheme: theme === 'auto' ? systemTheme : theme } 
    }));
  }, [systemTheme]);
  
  // Переключение между светлой и темной темой
  const toggleTheme = useCallback(() => {
    if (currentTheme === 'auto') {
      // Если auto, переключаем на противоположную системной
      setTheme(systemTheme === 'dark' ? 'light' : 'dark');
    } else {
      // Переключаем между light и dark
      setTheme(currentTheme === 'dark' ? 'light' : 'dark');
    }
  }, [currentTheme, systemTheme, setTheme]);
  
  // Получение конфигурации для Ant Design
  const getAntdConfig = useCallback((isMiniApp: boolean = false) => {
    return getAntdThemeConfig(currentTheme, isMiniApp);
  }, [currentTheme]);
  
  // Отслеживание системной темы
  useEffect(() => {
    const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
    
    const handleSystemThemeChange = (e: MediaQueryListEvent) => {
      const newSystemTheme = e.matches ? 'dark' : 'light';
      console.log('🌙 System theme changed to:', newSystemTheme);
      
      setSystemTheme(newSystemTheme);
      
      // Если текущая тема auto, применяем новую системную тему
      if (currentTheme === 'auto') {
        applyTheme('auto');
        
        // Уведомляем об изменении
        window.dispatchEvent(new CustomEvent('themeChange', { 
          detail: { theme: 'auto', resolvedTheme: newSystemTheme } 
        }));
      }
    };
    
    // Подписываемся на изменения
    mediaQuery.addEventListener('change', handleSystemThemeChange);
    
    return () => {
      mediaQuery.removeEventListener('change', handleSystemThemeChange);
    };
  }, [currentTheme]);
  
  // Инициализация темы при монтировании
  useEffect(() => {
    console.log('🎨 Initializing theme system');
    console.log('Current theme:', currentTheme);
    console.log('System theme:', systemTheme);
    console.log('Resolved theme:', resolvedTheme);
    
    // Применяем текущую тему
    applyTheme(currentTheme);
  }, []); // Только при монтировании
  
  // Обновление при изменении темы
  useEffect(() => {
    console.log('🎨 Theme updated:', {
      current: currentTheme,
      resolved: resolvedTheme,
      system: systemTheme,
    });
  }, [currentTheme, resolvedTheme, systemTheme]);
  
  return {
    currentTheme,
    resolvedTheme,
    systemTheme,
    setTheme,
    toggleTheme,
    isDark,
    isLight,
    isAuto,
    getAntdConfig,
    availableThemes,
  };
};

// ===== ДОПОЛНИТЕЛЬНЫЕ ХУКИ =====

/**
 * Хук для получения CSS переменных темы
 */
export const useThemeVariables = () => {
  const { resolvedTheme } = useTheme();
  
  return useCallback((variable: string) => {
    const element = document.documentElement;
    return getComputedStyle(element).getPropertyValue(`--sp-${variable}`).trim();
  }, [resolvedTheme]);
};

/**
 * Хук для адаптивных стилей в зависимости от темы
 */
export const useThemeStyles = () => {
  const { resolvedTheme, isDark, isLight } = useTheme();
  
  return {
    theme: resolvedTheme,
    isDark,
    isLight,
    
    // Готовые стили для частых случаев
    cardStyle: {
      background: 'var(--sp-bg-card)',
      border: '1px solid var(--sp-border-primary)',
      borderRadius: 'var(--sp-radius-lg)',
      boxShadow: 'var(--sp-shadow-md)',
      backdropFilter: 'blur(10px)',
    },
    
    textStyle: {
      primary: { color: 'var(--sp-text-primary)' },
      secondary: { color: 'var(--sp-text-secondary)' },
      tertiary: { color: 'var(--sp-text-tertiary)' },
    },
    
    buttonStyle: {
      primary: {
        background: 'var(--sp-color-primary)',
        color: 'var(--sp-text-inverse)',
        border: 'none',
        borderRadius: 'var(--sp-radius-md)',
      },
      secondary: {
        background: 'var(--sp-bg-secondary)',
        color: 'var(--sp-text-primary)',
        border: '1px solid var(--sp-border-primary)',
        borderRadius: 'var(--sp-radius-md)',
      },
    },
  };
};

/**
 * Хук для отслеживания изменений темы
 */
export const useThemeListener = (callback: (theme: ThemeName, resolvedTheme: 'light' | 'dark') => void) => {
  useEffect(() => {
    const handleThemeChange = (event: CustomEvent) => {
      callback(event.detail.theme, event.detail.resolvedTheme);
    };
    
    window.addEventListener('themeChange', handleThemeChange as EventListener);
    
    return () => {
      window.removeEventListener('themeChange', handleThemeChange as EventListener);
    };
  }, [callback]);
};

export default useTheme;
