import React from 'react';
import { HashRouter, Routes, Route, useNavigate } from 'react-router-dom';
import { ConfigProvider } from 'antd';
import { PermissionsProvider } from '../hooks/usePermissions';
import { useTheme } from '../hooks/useTheme';
import { buildAuthHeaders, ensureBackendAuth } from '../api';
const GrafanaLauncher = React.lazy(() => import('../pages/GrafanaLauncher'));

const ModernHeader = React.lazy(() => import('../components/ModernHeader'));
const TelegramHome = React.lazy(() => import('../pages/TelegramHome'));
const RealtimeVoiceChat = React.lazy(() => import('../pages/RealtimeVoiceChat'));
const MiniAppChat = React.lazy(() => import('../pages/MiniAppChat'));
const Prompts = React.lazy(() => import('../pages/Prompts'));
const PromptsStandalone = React.lazy(() => import('../pages/PromptsStandalone'));
const Settings = React.lazy(() => import('../pages/Settings'));
const LLMSettings = React.lazy(() => import('../pages/LLMSettings'));
const PhiSettings = React.lazy(() => import('../pages/PhiSettings'));
const Keywords = React.lazy(() => import('../pages/Keywords'));
const DatesRemindersV2 = React.lazy(() => import('../pages/DatesRemindersV2'));
const Payments = React.lazy(() => import('../pages/Payments'));
const Help = React.lazy(() => import('../pages/Help'));
const TelegramChat = React.lazy(() => import('../pages/TelegramChat'));
const ChatManagement = React.lazy(() => import('../pages/ChatManagement'));
const WebAuth = React.lazy(() => import('../pages/WebAuth'));
const ArchitectPanel = React.lazy(() => import('../pages/ArchitectPanel'));
const RBACAdmin = React.lazy(() => import('../pages/RBACAdmin'));
const SoulDashboard = React.lazy(() => import('../pages/SoulDashboard'));
const SoulGoals = React.lazy(() => import('../pages/SoulGoals'));
const SecurityDashboard = React.lazy(() => import('../pages/SecurityDashboard'));
const SecurityEvents = React.lazy(() => import('../pages/SecurityEvents'));
const ActivityGoalsIntegration = React.lazy(() => import('../pages/ActivityGoalsIntegration'));
const SoulOptimization = React.lazy(() => import('../pages/SoulOptimization'));
const SoulVisualization = React.lazy(() => import('../pages/SoulVisualization'));
const SoulLogs = React.lazy(() => import('../pages/SoulLogs'));
const SystemSettings = React.lazy(() => import('../pages/SystemSettings'));
const AdminPanel = React.lazy(() => import('../pages/AdminPanel'));
const AllPages = React.lazy(() => import('../pages/AllPages'));

const RequireAuth: React.FC<{ title?: string }> = ({ title = 'Требуется авторизация' }) => (
  <div style={{padding:16}}>
    <div style={{background:'var(--sp-bg-card, #111827)', border:'1px solid var(--sp-border-primary, #334155)', borderRadius:12, padding:16}}>
      <div style={{fontSize:18, fontWeight:700, marginBottom:8}}>🔒 {title}</div>
      <div style={{opacity:0.85, marginBottom:12}}>Откройте мини‑приложение через inline‑кнопку бота, чтобы загрузить данные пользователя.</div>
    </div>
  </div>
);

export const MiniShell: React.FC = () => {
  const { getAntdConfig } = useTheme();
  const [hasTgId, setHasTgId] = React.useState<boolean>(() => {
    try {
      const sid = sessionStorage.getItem('tg_id');
      const waUid = (window as any).Telegram?.WebApp?.initDataUnsafe?.user?.id;
      return !!(sid || waUid);
    } catch { return false; }
  });

  React.useEffect(() => {
    try {
      document.body.classList.add('telegram-mini-app');
      (window as any).Telegram?.WebApp?.ready?.();
      (window as any).Telegram?.WebApp?.expand?.();
      // Фикс: сохраняем tg_id сразу, чтобы меню/запросы имели идентификатор
      try {
        const waUid = (window as any).Telegram?.WebApp?.initDataUnsafe?.user?.id;
        if (waUid) {
          sessionStorage.setItem('tg_id', String(waUid));
          setHasTgId(true);
          try { window.dispatchEvent(new Event('sp:auth')); } catch {}
        } else {
          // Доп. фолбэк: парсим initData строку и извлекаем user.id
          const wa = (window as any).Telegram?.WebApp;
          const initDataStr = (wa && typeof wa.initData === 'string' && wa.initData.length ? wa.initData : '') as string;
          if (initDataStr) {
            try {
              const params = new URLSearchParams(initDataStr);
              const userJson = params.get('user');
              if (userJson) {
                const userObj = JSON.parse(userJson);
                if (userObj?.id) {
                  sessionStorage.setItem('tg_id', String(userObj.id));
                  setHasTgId(true);
                  try { window.dispatchEvent(new Event('sp:auth')); } catch {}
                }
              }
            } catch {}
          }
        }
      } catch {}
    } catch {}
    // Поллинг появления tg_id на старте, если initData приходит с задержкой
    let timer: any = null;
    let tries = 0;
    const check = () => {
      try {
        const sid = sessionStorage.getItem('tg_id');
        const waUid = (window as any).Telegram?.WebApp?.initDataUnsafe?.user?.id;
        if (sid || waUid) {
          if (!sid && waUid) { try { sessionStorage.setItem('tg_id', String(waUid)); } catch {} }
          setHasTgId(true);
          try { window.dispatchEvent(new Event('sp:auth')); } catch {}
          return;
        }
      } catch {}
      if (++tries < 40) { timer = setTimeout(check, 500); }
    };
    if (!hasTgId) {
      check();
    }
    return () => { if (timer) try { clearTimeout(timer); } catch {} };
  }, []);

  // Ранняя backend‑авторизация по initData (JWT), если ещё нет токена
  React.useEffect(() => {
    try {
      const hasToken = !!(sessionStorage.getItem('token') || localStorage.getItem('token'));
      const wa = (window as any).Telegram?.WebApp;
      const initDataStr = (wa && typeof wa.initData === 'string' && wa.initData.length ? wa.initData : '') as string;
      if (!hasToken && initDataStr) {
        void (async () => { try { await ensureBackendAuth(); } catch {} })();
      }
    } catch {}
  }, []);

  // Устанавливаем краткоживущую веб‑сессию (HttpOnly cookie sp_web) для домена
  React.useEffect(() => {
    const issueWebCookie = async () => {
      try {
        const wa = (window as any).Telegram?.WebApp;
        const waUid = wa?.initDataUnsafe?.user?.id;
        const initData = (wa && typeof wa.initData === 'string' && wa.initData.length ? wa.initData : '') as string;
        if (!waUid && !initData) return;
        const resp = await fetch('/api/web-auth/issue-web-cookie', {
          method: 'POST',
          headers: { ...(buildAuthHeaders() as any) },
          credentials: 'include',
          body: initData ? JSON.stringify({ initData }) : undefined,
        });
        const origin = (window.location && window.location.origin) || 'https://mini.soulpulse.art';
        if (!resp.ok) {
          // Fallback: OTP‑рукопожатие, затем сохраняем JWT локально
          try {
            const h = new Headers();
            if (waUid) h.append('X-Telegram-User-ID', String(waUid));
            const r1 = await fetch('/api/web-auth/issue-one-time-token', { method: 'POST', headers: h, credentials: 'include' });
            if (r1.ok) {
              const j = await r1.json();
              // Пытаемся сразу открыть веб‑окно с авторизацией через OTP (на стороне WEB будет установлен токен/кука)
              // Не выбрасываем из MiniApp: показываем модальное окно/сигнализируем событием, Web сможет открыть вручную при необходимости
              try { window.dispatchEvent(new CustomEvent('sp:otp-issued', { detail: { tg_id: Number(waUid), otp: j.otp } })); } catch {}
              const r2 = await fetch('/api/web-auth/verify-otp', {
                method: 'POST',
                headers: new Headers({ 'Content-Type': 'application/json' }),
                credentials: 'include',
                body: JSON.stringify({ tg_id: Number(waUid), otp: j.otp })
              });
              if (r2.ok) {
                try { const data = await r2.json(); if (data?.token) { sessionStorage.setItem('token', data.token); } } catch {}
              }
            }
          } catch {}
        } else {
          // Куки выданы — остаёмся в MiniApp (не открываем веб вне WebView)
        }
        try { window.dispatchEvent(new Event('sp:webcookie')); } catch {}
      } catch {}
    };
    issueWebCookie();
  }, []);

  // Стартовая навигация по start_param из Telegram (deep link startapp)
  const StartParamRouter: React.FC = () => {
    const navigate = useNavigate();
    React.useEffect(() => {
      try {
        const w: any = window as any;
        const sp = (w?.Telegram?.WebApp?.initDataUnsafe?.start_param || w?.Telegram?.WebApp?.startParam || '').toString().toLowerCase();
        if (!sp) return;
        const map: Record<string, string> = {
          'home': '/',
          'chat': '/chat',
          'prompts': '/prompts',
          'voice': '/realtime-voice',
          'realtime': '/realtime-voice',
          'all': '/all-pages',
          'settings': '/settings',
          'help': '/help',
          'payments': '/payments',
          'keywords': '/keywords',
          'reminders': '/dates-reminders'
        };
        const route = map[sp] || '/';
        navigate(route, { replace: true });
      } catch {}
    }, [navigate]);
    return null;
  };

  return (
    <ConfigProvider theme={getAntdConfig(true)}>
      <HashRouter>
        <PermissionsProvider>
          <div className={'telegram-mini-app'} style={{minHeight:'100dvh', display:'flex', flexDirection:'column'}}>
            <div style={{position:'sticky', top:0, zIndex:1000}}>
              <React.Suspense fallback={<div className="screen loading"><div className="spinner" /></div>}>
                <ModernHeader activePersonality={undefined} />
              </React.Suspense>
            </div>
            <div style={{flex:1, overflow:'auto'}}>
              <React.Suspense fallback={<div className="screen loading"><div className="spinner" /></div>}>
                <StartParamRouter />
                {hasTgId ? (
                  <Routes>
                    <Route path="/" element={<TelegramHome />} />
                    <Route path="/webauth" element={<WebAuth />} />
                    <Route path="/chat" element={<MiniAppChat />} />
                    <Route path="/realtime-voice" element={<RealtimeVoiceChat />} />
                    <Route path="/prompts" element={<PromptsStandalone />} />
                    <Route path="/grafana" element={<GrafanaLauncher />} />
                    <Route path="/grafana/*" element={<GrafanaLauncher />} />
                    <Route path="/all-pages" element={<AllPages />} />
                    <Route path="/settings" element={<Settings prompts={[]} />} />
                    <Route path="/llm-settings" element={<LLMSettings />} />
                    <Route path="/phi-settings" element={<PhiSettings />} />
                    <Route path="/phi-settings" element={<PhiSettings />} />
                    <Route path="/payments" element={<Payments />} />
                    <Route path="/help" element={<Help />} />
                    <Route path="/telegram-chat" element={<TelegramChat />} />
                    <Route path="/chat-management" element={<ChatManagement />} />
                    <Route path="/keywords" element={<Keywords />} />
                    <Route path="/dates-reminders" element={<DatesRemindersV2 />} />
                    {/* Архитектор/Админ/Soul */}
                    <Route path="/architect" element={<ArchitectPanel />} />
                    <Route path="/rbac-admin" element={<RBACAdmin />} />
                    <Route path="/soul/dashboard" element={<SoulDashboard />} />
                    <Route path="/soul/goals" element={<SoulGoals />} />
                    <Route path="/soul/activities-goals" element={<ActivityGoalsIntegration />} />
                    <Route path="/soul/optimization" element={<SoulOptimization />} />
                    <Route path="/soul/visualization" element={<SoulVisualization />} />
                    <Route path="/soul/logs" element={<SoulLogs />} />
                    <Route path="/admin" element={<AdminPanel />} />
                    <Route path="/admin/settings" element={<SystemSettings />} />
                    <Route path="/security" element={<SecurityDashboard />} />
                    <Route path="/security/events" element={<SecurityEvents />} />
                    <Route path="*" element={<TelegramHome />} />
                  </Routes>
                ) : (
                  <Routes>
                    <Route path="/" element={<TelegramHome />} />
                    <Route path="/webauth" element={<WebAuth />} />
                    <Route path="/all-pages" element={<AllPages />} />
                    <Route path="/grafana" element={<GrafanaLauncher />} />
                    <Route path="/grafana/*" element={<GrafanaLauncher />} />
                    <Route path="/chat" element={<RequireAuth title="Чат доступен после входа" />} />
                    <Route path="/prompts" element={<RequireAuth title="Личности доступны после входа" />} />
                    <Route path="/settings" element={<RequireAuth title="Настройки доступны после входа" />} />
                    <Route path="/llm-settings" element={<RequireAuth title="Параметры ИИ доступны после входа" />} />
                    <Route path="/phi-settings" element={<RequireAuth title="Параметры Phi доступны после входа" />} />
                    <Route path="/payments" element={<RequireAuth title="Платежи доступны после входа" />} />
                    <Route path="/help" element={<RequireAuth title="Справка доступна после входа" />} />
                    <Route path="/chat-management" element={<RequireAuth title="Управление чатом после входа" />} />
                    <Route path="/keywords" element={<RequireAuth title="Ключевые слова после входа" />} />
                    <Route path="/dates-reminders" element={<RequireAuth title="Даты и напоминания после входа" />} />
                    <Route path="/architect" element={<RequireAuth title="Требуется роль и вход" />} />
                    <Route path="/rbac-admin" element={<RequireAuth title="Требуется роль и вход" />} />
                    <Route path="/security/*" element={<RequireAuth title="Security после входа" />} />
                    <Route path="/soul/*" element={<RequireAuth title="Модуль Soul после входа" />} />
                    <Route path="*" element={<TelegramHome />} />
                  </Routes>
                )}
              </React.Suspense>
            </div>
          </div>
        </PermissionsProvider>
      </HashRouter>
    </ConfigProvider>
  );
};

export default MiniShell;


