import { logger } from './utils/logger';

// Для локальной разработки используем localhost:8000, для продакшена - относительный путь
const API_BASE = (() => {
  logger.debug('[API_BASE] 🎯 Определяем API_BASE...');

  const envBase = (import.meta as any).env?.VITE_API_URL as string | undefined;
  const host = typeof window !== 'undefined' ? window.location.hostname : '';
  const protocol = typeof window !== 'undefined' ? window.location.protocol : 'http:';
  const port = typeof window !== 'undefined' ? window.location.port : '';

  logger.debug('[API_BASE] 🌐 Host:', host);
  logger.debug('[API_BASE] 🔗 Protocol:', protocol);
  logger.debug('[API_BASE] 🚪 Port:', port);
  logger.debug('[API_BASE] 📝 VITE_API_URL:', envBase);

  // Хосты *.soulpulse.art всегда используют относительный /api (чтобы не уехать на localhost)
  if (host.endsWith('soulpulse.art')) {
    const relativeBase = '/api';
    logger.info('[API_BASE] ✅ Using relative API for production domain:', relativeBase);
    return relativeBase;
  }

  // Приоритет: явная переменная окружения (не для *.soulpulse.art)
  if (envBase && envBase.trim()) {
    const cleanEnvBase = envBase.replace(/\/$/, '');
    logger.info('[API_BASE] ✅ Using VITE_API_URL:', cleanEnvBase);
    return cleanEnvBase;
  }

  const isLocal = host === 'localhost' || host === '127.0.0.1';

  // Локально ходим на локальный бэкенд
  if (isLocal) {
    const localBase = 'http://localhost:8000/api';
    logger.info('[API_BASE] ✅ Using local API_BASE:', localBase);
    return localBase;
  }

  // В продакшене используем относительный путь (тот же домен)
  const relativeBase = '/api';
  logger.info('[API_BASE] ✅ Using relative API_BASE:', relativeBase);
  return relativeBase;
})();

// Экспортируем API_BASE для отладки
export { API_BASE };
logger.info('[API] 🎯 Итоговый API_BASE:', API_BASE);

function getStoredToken(): string | null {
  try { return sessionStorage.getItem('token') || localStorage.getItem('token'); } catch { return null; }
}

function base64UrlDecode(input: string): string {
  try {
    const pad = (s: string) => s + '='.repeat((4 - (s.length % 4)) % 4);
    const b64 = pad(input.replace(/-/g, '+').replace(/_/g, '/'));
    if (typeof atob === 'function') {
      return decodeURIComponent(Array.prototype.map.call(atob(b64), (c: string) => '%'+('00'+c.charCodeAt(0).toString(16)).slice(-2)).join(''));
    }
  } catch {}
  return '';
}

function decodeJwtPayload(token: string): any | null {
  try {
    const parts = token.split('.');
    if (parts.length < 2) return null;
    const json = base64UrlDecode(parts[1]);
    return JSON.parse(json);
  } catch { return null; }
}

function isTokenValidForCurrentSession(token: string): boolean {
  try {
    const payload = decodeJwtPayload(token);
    if (!payload) return false;
    // exp в секундах
    const nowSec = Math.floor(Date.now() / 1000);
    const skew = 30; // 30s допуск
    if (typeof payload.exp === 'number' && payload.exp <= nowSec + skew) return false;
    // Реальный мини‑апп только если есть initDataUnsafe.user.id или непустой initData
    const wa = (typeof window !== 'undefined') ? (window as any).Telegram?.WebApp : undefined;
    const isMiniApp = !!(wa && ((wa as any).initDataUnsafe?.user?.id || (typeof (wa as any).initData === 'string' && (wa as any).initData.length > 0)));
    const sessionTg = (() => { try { return sessionStorage.getItem('tg_id'); } catch { return null; } })();
    const claimTg = String(payload.tg_id || payload.sub || '');
    // В вебе требуем наличие tg_id в токене; мини‑апп допускает отсутствие claim при первом тике
    if (!isMiniApp) {
      // WEB: допускаем отсутствие claim в JWT, если есть tg_id в сессии (fallback для старых токенов)
      if (!claimTg && sessionTg) return true;
      if (!claimTg && !sessionTg) return false;
      if (sessionTg && claimTg !== sessionTg) return false;
    } else {
      if (claimTg && sessionTg && claimTg !== sessionTg) return false;
    }
    return true;
  } catch { return false; }
}

function getValidTokenOrClear(): string | null {
  const token = getStoredToken();
  if (!token) return null;
  if (isTokenValidForCurrentSession(token)) return token;
  try { sessionStorage.removeItem('token'); } catch {}
  try { localStorage.removeItem('token'); } catch {}
  return null;
}

export function buildAuthHeaders(): HeadersInit {
  const headers: Record<string, string> = { "Content-Type": "application/json" };
  let tgId = sessionStorage.getItem('tg_id')
    || (typeof window !== 'undefined' ? localStorage.getItem('tg_id') : null)
    || (typeof window !== 'undefined' && (window as any).Telegram?.WebApp?.initDataUnsafe?.user?.id?.toString())
    || '';
  if (tgId) headers['X-Telegram-User-ID'] = tgId;
  try {
    const initData = (typeof window !== 'undefined') ? (window as any).Telegram?.WebApp?.initData : undefined;
    if (initData && typeof initData === 'string' && initData.length) {
      headers['X-Telegram-Init-Data'] = initData;
      // Fallback: извлекаем user.id из initData, если tg_id ещё не найден
      if (!tgId) {
        try {
          const params = new URLSearchParams(initData);
          const userJson = params.get('user');
          if (userJson) {
            const userObj = JSON.parse(userJson);
            const parsedId = userObj?.id;
            if (parsedId) {
              tgId = String(parsedId);
              headers['X-Telegram-User-ID'] = tgId;
              try { sessionStorage.setItem('tg_id', tgId); } catch {}
              try { localStorage.setItem('tg_id', tgId); } catch {}
            }
          }
        } catch {}
      }
    }
  } catch {}
  const token = getValidTokenOrClear();
  if (token) headers['Authorization'] = `Bearer ${token}`;

  // Синхронизация tg_id из JWT, если он отсутствует в сессии (веб-режим)
  try {
    if (!tgId && token) {
      const payload = decodeJwtPayload(token);
      const claimTg = String((payload as any)?.tg_id || (payload as any)?.sub || '');
      if (claimTg) {
        try { sessionStorage.setItem('tg_id', claimTg); } catch {}
        headers['X-Telegram-User-ID'] = claimTg;
      }
    }
  } catch {}
  return headers;
}

// Экспорт валидности токена для использования в UI
export function hasValidAuthToken(): boolean {
  return !!getValidTokenOrClear();
}

export async function api<T>(path: string, opts: RequestInit = {}): Promise<T> {
  const doFetch = async (): Promise<Response> => {
    const headers: HeadersInit = { ...buildAuthHeaders(), ...(opts.headers || {}) };
    return fetch(`${API_BASE}${path}`, { credentials: 'include', ...opts, headers });
  };

  let res = await doFetch();
  if (res.status === 401) {
    try {
      // Пытаемся выполнить backend‑авторизацию из MiniApp и повторить запрос один раз
      const wa: any = (typeof window !== 'undefined') ? (window as any).Telegram?.WebApp : undefined;
      const initData: string | undefined = (wa && typeof wa.initData === 'string' && wa.initData.length ? wa.initData : undefined) as any;
      if (initData) {
        await authenticateWithBackend(initData);
        res = await doFetch();
      }
    } catch {}
  }
  if (res.status === 401) {
    // Автоматический OTP‑фоллбек (чистый WEB или MiniApp без успешной verify)
    try {
      const wa: any = (typeof window !== 'undefined') ? (window as any).Telegram?.WebApp : undefined;
      const uidFromWa = (() => { try { return wa?.initDataUnsafe?.user?.id ? String(wa.initDataUnsafe.user.id) : ''; } catch { return ''; } })();
      const uidFromStore = (() => { try { return sessionStorage.getItem('tg_id') || localStorage.getItem('tg_id') || ''; } catch { return ''; } })();
      const tgId = uidFromWa || uidFromStore;
      if (tgId) {
        const h = new Headers();
        h.append('X-Telegram-User-ID', tgId);
        // 1) Получаем одноразовый код
        const r1 = await fetch(`${API_BASE}/web-auth/issue-one-time-token`, { method: 'POST', headers: h, credentials: 'include' });
        if (r1.ok) {
          const j = await r1.json();
          // 2) Подтверждаем OTP, сервер установит куку и вернёт токен
          const r2 = await fetch(`${API_BASE}/web-auth/verify-otp`, {
            method: 'POST',
            headers: new Headers({ 'Content-Type': 'application/json' }),
            credentials: 'include',
            body: JSON.stringify({ tg_id: Number(tgId), otp: j.otp })
          });
          if (r2.ok) {
            try {
              const data = await r2.json();
              if (data?.token) {
                sessionStorage.setItem('token', data.token);
                try { sessionStorage.setItem('tg_id', tgId); } catch {}
                try { localStorage.setItem('tg_id', tgId); } catch {}
                try { window.dispatchEvent(new Event('sp:auth')); } catch {}
              }
            } catch {}
            // Повторяем изначальный запрос уже с токеном/кукой
            res = await doFetch();
          }
        }
      }
    } catch {}
  }
  if (!res.ok) throw new Error(`${res.status} ${res.statusText}`);
  return res.json();
}

// Авторизация через backend API
async function authenticateWithBackend(initData: string): Promise<void> {
  try {
    logger.info('[AUTH] 🔐 Authenticating with backend...');
    
    // Используем dev endpoint для локального тестирования
    const endpoint = window.location.hostname === 'localhost' 
      ? '/miniapp/auth/verify-dev' 
      : '/miniapp/auth/verify';
    
    const response = await fetch(`${API_BASE}${endpoint}`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ initData }),
    });

    if (response.ok) {
      const data = await response.json();
      logger.info('[AUTH] ✅ Backend auth successful');
      
      // Сохраняем JWT токен
      if (data.token) {
        sessionStorage.setItem('token', data.token);
        logger.debug('[AUTH] 💾 JWT token saved');
      }
      
      // Сохраняем данные пользователя
      if (data.user) {
        sessionStorage.setItem('user', JSON.stringify(data.user));
        logger.debug('[AUTH] 👤 User data saved');
      }
      // Синхронизируем tg_id из ответа (user.tg_id | tg_id | user.id)
      try {
        const respTg = String((data?.user?.tg_id) || (data?.tg_id) || (data?.user?.id) || '');
        if (respTg) {
          try { sessionStorage.setItem('tg_id', respTg); } catch {}
          try { localStorage.setItem('tg_id', respTg); } catch {}
          logger.info('[AUTH] 🔗 tg_id synchronized from backend:', respTg);
        }
      } catch {}

    } else {
      logger.error('[AUTH] ❌ Backend auth failed:', response.status, response.statusText);
      const errorText = await response.text();
      logger.error('[AUTH] 📄 Error details:', errorText);
    }
  } catch (error) {
    logger.error('[AUTH] 💥 Backend auth error:', error);
  }
}

// Публичная обёртка: гарантирует, что если у нас есть initData WebApp, то
// будет выполнена backend‑авторизация и валидный JWT окажется в sessionStorage.
export async function ensureBackendAuth(): Promise<boolean> {
  try {
    // Если уже есть валидный токен — ничего не делаем
    if (hasValidAuthToken()) return true;
    const wa = (typeof window !== 'undefined') ? (window as any).Telegram?.WebApp : undefined;
    const initData: string | undefined = (wa && typeof wa.initData === 'string' && wa.initData.length ? wa.initData : undefined) as any;
    if (!initData) return false;
    // Гарантируем ready() и пытаемся синхронизировать tg_id из initDataUnsafe.user
    try { wa?.ready?.(); } catch {}
    try {
      const uid = wa?.initDataUnsafe?.user?.id;
      if (uid) {
        try { sessionStorage.setItem('tg_id', String(uid)); } catch {}
      }
    } catch {}
    await authenticateWithBackend(initData);
    return hasValidAuthToken();
  } catch {
    return false;
  }
}

// Функция для получения данных пользователя Telegram
export function getTelegramUser() {
  const timestamp = new Date().toISOString();
  logger.debug(`[${timestamp}] [AUTH] 🔍 Проверяем Telegram WebApp...`);
  logger.debug(`[${timestamp}] [AUTH] 🌐 Window defined:`, typeof window !== 'undefined');
  logger.debug(`[${timestamp}] [AUTH] 📱 Telegram exists:`, !!(window as any).Telegram);
  logger.debug(`[${timestamp}] [AUTH] 🤖 WebApp exists:`, !!(window as any).Telegram?.WebApp);
  logger.debug(`[${timestamp}] [AUTH] 👤 initDataUnsafe.user exists:`, !!(window as any).Telegram?.WebApp?.initDataUnsafe?.user);

  // 0) Быстрый путь для веб-версии: сначала пробуем SessionStorage
  const storedUser = sessionStorage.getItem('telegram_user');
  const tgId = sessionStorage.getItem('tg_id');

  logger.debug(`[${timestamp}] [AUTH] 💾 SessionStorage tg_id:`, tgId);
  logger.debug(`[${timestamp}] [AUTH] 💾 SessionStorage user:`, storedUser);

  if (storedUser && tgId) {
    try {
      const user = JSON.parse(storedUser);
      logger.debug(`[${timestamp}] [AUTH] ✅ User from sessionStorage:`, user.id);
      return user;
    } catch (e) {
      logger.warn(`[${timestamp}] [AUTH] Ошибка парсинга данных пользователя из sessionStorage:`, e);
    }
  }

  // 1) Минимальная проверка: берем tg_id из Telegram WebApp или sessionStorage
  try {
    const wa = (window as any).Telegram?.WebApp;
    // Гарантируем ready(), если доступно
    try { wa?.ready?.(); } catch {}
    const uid = wa?.initDataUnsafe?.user?.id;
    const initDataStr: string | undefined = (wa && typeof wa.initData === 'string' && wa.initData.length ? wa.initData : undefined) as any;
    if (uid) {
      try { sessionStorage.setItem('tg_id', String(uid)); } catch {}
      // Если есть initData — сразу инициируем backend-авторизацию для выдачи JWT
      if (initDataStr) {
        try { authenticateWithBackend(initDataStr); } catch {}
      }
      return { id: uid } as any;
    }
    // Если user пока нет, но initData присутствует — попробуем авторизоваться бэкендом, чтобы получить JWT и tg_id позже
    if (!uid && initDataStr) {
      try {
        // Парсим querystring initData и извлекаем user.id
        const params = new URLSearchParams(initDataStr);
        const userJson = params.get('user');
        if (userJson) {
          const userObj = JSON.parse(userJson);
          const parsedId = userObj?.id;
          if (parsedId) {
            try { sessionStorage.setItem('tg_id', String(parsedId)); } catch {}
            // параллельно инициируем backend-verify для выдачи JWT
            try { authenticateWithBackend(initDataStr); } catch {}
            return { id: parsedId } as any;
          }
        }
        // Без user — всё равно дергаем бэкенд для выдачи JWT (если сервер сможет вытащить)
        authenticateWithBackend(initDataStr);
      } catch {
        try { authenticateWithBackend(initDataStr); } catch {}
      }
    }
  } catch {}

  if (tgId) {
    // Если есть только tg_id, создаем минимальный объект пользователя
    const user = { id: parseInt(tgId, 10) };
    console.log(`[${timestamp}] [AUTH] ⚠️ Только tg_id из sessionStorage:`, user.id);
    return user as any;
  }

  logger.warn(`[${timestamp}] [AUTH] Пользователь недоступен (ни SessionStorage, ни WebApp). Для web требуется /webauth.`);
  return null as any;
}

// Универсальная функция для API запросов с поддержкой различных методов
export async function apiRequest(
  url: string,
  method: 'GET' | 'POST' | 'PUT' | 'DELETE' = 'GET',
  body: any = null,
  customHeaders: Record<string, string> = {}
): Promise<any> {
  logger.debug('[API] 🚀 Начинаем API запрос...');
  logger.debug('[API] 📍 URL:', url);
  logger.debug('[API] 📝 Method:', method);
  logger.debug('[API] 📦 Body:', body);
  logger.debug('[API] 📋 Custom headers:', customHeaders);

  const headers: HeadersInit = { ...buildAuthHeaders(), ...customHeaders };

  const options: RequestInit = {
    method,
    headers,
    credentials: 'include',
  };

  if (body && method !== 'GET') {
    options.body = JSON.stringify(body);
  }

  // Добавляем timestamp для обхода кэширования
  const separator = url.includes('?') ? '&' : '?';
  const timestampedUrl = `${url}${separator}_cache_bust=${Date.now()}`;
  const fullUrl = timestampedUrl.startsWith('http') ? timestampedUrl : `${API_BASE}${timestampedUrl}`;

  logger.debug('[API] 🌐 Final URL:', fullUrl);
  logger.debug('[API] 🏠 API_BASE:', API_BASE);
  logger.debug('[API] ⚙️ Request options:', JSON.stringify(options, null, 2));

  try {
    logger.debug('[API] 📡 Отправляем запрос...');
    const response = await fetch(fullUrl, options);
    logger.debug('[API] 📶 Response status:', response.status);
    logger.debug('[API] 📶 Response statusText:', response.statusText);
    logger.debug('[API] 📶 Response headers:', Object.fromEntries(response.headers.entries()));

    if (!response.ok) {
      const errorText = await response.text();
      logger.error('[API] ❌ HTTP Error:', response.status, response.statusText);
      logger.error('[API] 📄 Error response text:', errorText);
      // Локальная обработка 401: не делаем глобальных редиректов здесь
      if (response.status === 401) {
        const err = new Error(`HTTP 401 Unauthorized`);
        (err as any).status = 401;
        (err as any).raw = errorText;
        throw err;
      }
      throw new Error(`HTTP ${response.status}: ${response.statusText} - ${errorText}`);
    }

    // Проверяем Content-Type
    const contentType = response.headers.get('Content-Type') || '';
    logger.debug('[API] 📋 Content-Type:', contentType);

    if (!contentType.includes('application/json')) {
      const htmlText = await response.text();
      logger.error('[API] 🚨 ПОЛУЧЕН HTML ВМЕСТО JSON!');
      logger.error('[API] 📄 HTML содержимое (первые 500 символов):', htmlText.substring(0, 500));
      throw new Error(`API вернул HTML вместо JSON! Content-Type: ${contentType}`);
    }

    const responseData = await response.json();
    logger.debug('[API] ✅ Успешный ответ:', JSON.stringify(responseData, null, 2));
    return responseData;

  } catch (error) {
    logger.error('[API] 💥 Ошибка при выполнении запроса:', error);
    throw error;
  }
}