// Простой ErrorBoundary для локальной диагностики
class LocalBoundary extends React.Component<{ label: string; children: React.ReactNode }, { hasError: boolean; err?: any }>{
  constructor(props:any){ super(props); this.state = { hasError: false }; }
  static getDerivedStateFromError(error:any){ return { hasError: true, err: error }; }
  componentDidCatch(error:any, info:any){ try{ console.error('[LocalBoundary]', this.props.label, error, info); }catch{} }
  render(){ if(this.state.hasError){ return (
    <div style={{padding:12, margin:12, border:'1px dashed #ef4444', color:'#ef4444', background:'rgba(239,68,68,0.06)', borderRadius:8}}>
      <div style={{fontWeight:700}}>Сбой в секции: {this.props.label}</div>
      <div style={{fontSize:12, whiteSpace:'pre-wrap'}}>{String(this.state.err||'')}</div>
    </div>
  ); } return this.props.children as any; }
}

// Глобальный гард регистрации: если у пользователя роль start — отправляем на /register
const RegistrationGuard: React.FC<{ noRedirect?: boolean }> = ({ noRedirect = false }) => {
  const { state } = usePermsHook();
  useEffect(() => {
    try {
      const hasStart = state.roles.some(r => r.name === 'start');
      const path = window.location.pathname;
      // Не редиректим страницы архитектора, чтобы избежать сброса навигации
      if (hasStart && path !== '/register' && !path.startsWith('/architect')) {
        if (noRedirect === true) {
          console.log('[RegistrationGuard] start-role detected, but redirects disabled');
        } else {
          try { const u = new URL(window.location.href); u.hash = '#/register'; window.location.replace(u.toString()); } catch { try { window.location.hash = '#/register'; } catch {} }
        }
      }
    } catch {}
  }, [state.roles]);
  return null;
};

  // Ограничитель по ролям: показывает children только для нужных ролей (с мягким skeleton)
  const RoleGuard: React.FC<{ roles: string[]; children: React.ReactNode; fallback?: React.ReactNode }> = ({ roles, children, fallback = null }) => {
  const { state } = usePermsHook();
  const bypass = (() => { try { return (window as any).__SP_FLAGS__?.BYPASS_ROLE_GUARDS === true; } catch { return false; } })();
  if (bypass) return <>{children}</>;

  // P44: не показываем защищённый контент до загрузки ролей даже в Mini‑App
  try {
    const isTg = !!(window as any).Telegram?.WebApp;
    const tgId = (() => { try { return sessionStorage.getItem('tg_id'); } catch { return null; } })()
      || (window as any).Telegram?.WebApp?.initDataUnsafe?.user?.id?.toString() || null;
    if (isTg && (!tgId || state.loading)) {
      return <div className="screen loading"><div className="spinner" /></div>;
    }
  } catch {}

  // Пока роли загружаются — показываем мягкий skeleton вместо жёсткого спиннера
  if (state.loading) {
    return (
      <div style={{padding: 16}}>
        <div style={{height: 18, width: '40%', borderRadius: 9, background:'linear-gradient(90deg, rgba(200,200,200,0.25), rgba(160,160,160,0.35), rgba(200,200,200,0.25))', animation:'sp-skeleton 1.2s ease-in-out infinite', marginBottom: 12}} />
        <div style={{display:'grid', gridTemplateColumns:'1fr', gap:12}}>
          {Array.from({ length: 6 }).map((_,i)=> (
            <div key={i} style={{height: 64, borderRadius: 12, background:'linear-gradient(90deg, rgba(200,200,200,0.25), rgba(160,160,160,0.35), rgba(200,200,200,0.25))', animation:'sp-skeleton 1.2s ease-in-out infinite'}} />
          ))}
        </div>
      </div>
    );
  }

  const hasArchitect = state.roles.some(r => roles.includes(r.name));
  const hasAdmin = state.roles.some(r => r.name === 'admin');
  const allowed = hasArchitect || hasAdmin;
  if (!allowed) {
    return (
      <>{fallback || (
        <div style={{padding:16}}>
          <div style={{fontWeight:600, marginBottom:8}}>Недостаточно прав</div>
          <div style={{fontSize:12, opacity:0.8}}>Для доступа требуется роль: {roles.join(', ')}</div>
        </div>
      )}</>
    );
  }
  return <>{children}</>;
};
