import React, { useEffect, useMemo, useState } from 'react';
import { Table, Button, Space, Typography, Tag, Input, Select, message, Tooltip } from 'antd';
import { apiRequest } from '../api';
import { usePermissions } from '../hooks/usePermissions';

const { Title, Text } = Typography;

type VoiceSample = {
  id: number;
  label: string;
  provider: string;
  voice_id: string;
  rate: number;
  emotion: string;
  file_path: string;
  persona_key?: string | null;
  created_at?: string;
  updated_at?: string;
};

type Binding = {
  prompt_key: string;
  sample_id: number;
  label: string;
  provider: string;
  voice_id: string;
  rate: number;
  emotion: string;
  file_path: string;
};

const DEFAULT_PERSONAS = [
  { key: 'Soul_Core', label: 'Soul Core' },
  { key: 'Soul_Core_HF', label: 'Soul Human Fusion' },
  { key: 'FR_Ranevskaya_Persona_v1_4', label: 'Раневская' },
  { key: 'klee_masterpiece_v6_3', label: 'Кли' },
  { key: 'zhvan_prompt_clean_v3_3', label: 'Дядя Миша (Жванецкий)' },
  { key: 'Ved_prompt_Masterpiece_v4_3', label: 'Вед' },
  { key: 'Kabbalah_prompt-3_v16', label: 'Каббала' },
  { key: 'female_resonance', label: 'Female Resonance' },
  { key: 'LT_Prompt_Masterpiece_v1_9', label: 'Language Trainer' },
  { key: 'flow_prompt-3_v4', label: 'Поток' },
];

const VoiceAdmin: React.FC = () => {
  const { hasRole } = usePermissions();
  const isAdminOrArchitect = useMemo(() => hasRole('admin') || hasRole('architect'), [hasRole]);

  const [loading, setLoading] = useState(false);
  const [samples, setSamples] = useState<VoiceSample[]>([]);
  const [bindings, setBindings] = useState<Binding[]>([]);
  const [filter, setFilter] = useState('');
  const [bindPersona, setBindPersona] = useState<Record<number, string>>({});

  const loadAll = async () => {
    try {
      setLoading(true);
      const s = await apiRequest('/voice/admin/samples', 'GET');
      const b = await apiRequest('/voice/admin/bindings', 'GET');
      const sItems: VoiceSample[] = Array.isArray(s?.items) ? s.items : (Array.isArray(s) ? s : []);
      const bItems: Binding[] = Array.isArray(b?.items) ? b.items : (Array.isArray(b) ? b : []);
      setSamples(sItems);
      setBindings(bItems);
    } catch (e) {
      message.error('Не удалось загрузить список голосов');
    } finally { setLoading(false); }
  };

  useEffect(() => { void loadAll(); }, []);

  const filtered = useMemo(() => {
    const f = filter.trim().toLowerCase();
    if (!f) return samples;
    return samples.filter(s => [s.label, s.provider, s.voice_id, s.emotion, s.file_path, s.persona_key || '']
      .some(v => String(v).toLowerCase().includes(f)));
  }, [samples, filter]);

  const doBind = async (sample: VoiceSample) => {
    try {
      const personaKey = bindPersona[sample.id] || sample.persona_key || '';
      if (!personaKey) { message.warning('Выберите persona_key'); return; }
      const body = { persona_key: personaKey, voice_id: sample.voice_id, rate: sample.rate, pitch: 0.0 } as any;
      await apiRequest('/voice/set_voice', 'POST', body);
      message.success(`Привязано к ${personaKey}`);
      void loadAll();
    } catch (e) {
      message.error('Не удалось привязать голос');
    }
  };

  if (!isAdminOrArchitect) {
    return <div style={{ padding: 'var(--sp-spacing-sm)' }}><Title level={4}>Доступ ограничен</Title><Text>Требуется роль admin или architect.</Text></div>;
  }

  return (
    <div style={{ padding: 'var(--sp-spacing-sm)', boxSizing: 'border-box', maxWidth: '100%' }}>
      <Space direction="vertical" size="large" style={{ width: '100%' }}>
        <Title level={3} style={{ margin: 0 }}>Голоса (админ)</Title>
        <Space wrap>
          <Input placeholder="Фильтр" value={filter} onChange={e => setFilter(e.target.value)} allowClear style={{ width: 300 }} />
          <Button onClick={() => { setFilter(''); void loadAll(); }}>Обновить</Button>
        </Space>
        <Table
          rowKey="id"
          loading={loading}
          dataSource={filtered}
          pagination={{ pageSize: 10 }}
          columns={[
            { title: 'ID', dataIndex: 'id', width: 70 },
            { title: 'Label', dataIndex: 'label' },
            { title: 'Provider', dataIndex: 'provider', width: 120 },
            { title: 'Voice', dataIndex: 'voice_id', width: 120, render: (v) => <Tag color="geekblue">{v}</Tag> },
            { title: 'Rate', dataIndex: 'rate', width: 90 },
            { title: 'Emotion', dataIndex: 'emotion', width: 110 },
            {
              title: 'Preview', dataIndex: 'file_path', width: 260,
              render: (p: string) => (
                <audio controls preload="none" style={{ width: 240 }} src={`/api/voice/admin/file?path=${encodeURIComponent(p)}`} />
              )
            },
            {
              title: 'Persona', dataIndex: 'persona_key', width: 280,
              render: (pk: string | null, rec: VoiceSample) => (
                <Space>
                  <Select
                    showSearch
                    style={{ width: 220 }}
                    value={bindPersona[rec.id] ?? (pk || undefined)}
                    onChange={(v) => setBindPersona(prev => ({ ...prev, [rec.id]: v }))}
                    placeholder="persona_key"
                    options={DEFAULT_PERSONAS.map(p => ({ value: p.key, label: p.label }))}
                  />
                  <Tooltip title="Привязать голос к персоне">
                    <Button type="primary" onClick={() => void doBind(rec)}>Привязать</Button>
                  </Tooltip>
                </Space>
              )
            },
          ]}
        />
      </Space>
    </div>
  );
};

export default VoiceAdmin;


