import React, { createContext, useContext, useEffect, useState } from 'react';
import { buildAuthHeaders, ensureBackendAuth, api } from '../api';

// Типы для системы полномочий
export interface UserRole {
  id: number;
  name: string;
  description?: string;
  is_system: boolean;
}

export interface UserPermission {
  id: number;
  key: string;
  description?: string;
}

export interface UserLimits {
  daily_requests?: number;
  monthly_requests?: number;
  max_input_tokens?: number;
  max_output_tokens?: number;
}

export interface PermissionsState {
  roles: UserRole[];
  permissions: string[];
  limits: UserLimits;
  loading: boolean;
  error: string | null;
}

// Контекст для системы полномочий
const PermissionsContext = createContext<{
  state: PermissionsState;
  hasPermission: (permission: string) => boolean;
  hasRole: (roleName: string) => boolean;
  checkLimits: (action: string) => boolean;
  refreshPermissions: () => Promise<void>;
} | null>(null);

// Провайдер контекста полномочий
export const PermissionsProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [state, setState] = useState<PermissionsState>({
    roles: [],
    permissions: [],
    limits: {},
    loading: true,
    error: null,
  });

  // Внутренние маркеры для устранения "дрожания" ролей
  const inFlightRef = React.useRef<boolean>(false);
  const controllerRef = React.useRef<AbortController | null>(null);
  const seqRef = React.useRef<number>(0);
  const lastRolesKeyRef = React.useRef<string>('');

  const rolesToKey = (roles: { name: string }[]): string => {
    try {
      const names = roles.map(r => r.name).sort();
      return names.join('|');
    } catch { return ''; }
  };

  const mergeWithSticky = (roles: { id: number; name: string; description?: string }[]): { id: number; name: string; description?: string }[] => {
    try {
      const raw = sessionStorage.getItem('sp_roles_sticky');
      if (!raw) return roles;
      const sticky = JSON.parse(raw || '[]');
      const byName: Record<string, any> = Object.fromEntries(roles.map(r => [r.name, r]));
      for (const sr of Array.isArray(sticky) ? sticky : []) {
        if (sr && typeof sr.name === 'string' && !byName[sr.name]) {
          roles.push({ id: sr.id ?? -1, name: sr.name, description: sr.description });
        }
      }
      return roles;
    } catch { return roles; }
  };

  // Устанавливаем глобальный флаг обхода гардов для повышенных ролей (архитектор)
  const setBypassGuardFlag = (roles: { name: string }[]) => {
    try {
      const elevated = roles.some(r => r.name === 'architect');
      const root: any = (typeof window !== 'undefined') ? (window as any) : {};
      root.__SP_FLAGS__ = root.__SP_FLAGS__ || {};
      // Если архитектор — полностью отключаем ролевые гарды (устраняем мерцание/блокировки)
      root.__SP_FLAGS__.BYPASS_ROLE_GUARDS = elevated;
    } catch {}
  };

  const persistStickyIfElevated = (roles: { id: number; name: string; description?: string }[]) => {
    try {
      const elevated = roles.some(r => r.name === 'architect' || r.name === 'admin');
      if (!elevated) return;
      const names = new Set(roles.map(r => r.name));
      const payload = roles.filter(r => names.has(r.name));
      sessionStorage.setItem('sp_roles_sticky', JSON.stringify(payload));
    } catch {}
  };

  // Получение текущих полномочий пользователя
  const fetchPermissions = async () => {
    try {
      // Отмена предыдущего запроса, чтобы не применять устаревшие ответы
      if (controllerRef.current) {
        try { controllerRef.current.abort(); } catch {}
      }
      controllerRef.current = new AbortController();
      const mySeq = ++seqRef.current;
      if (inFlightRef.current) return;
      inFlightRef.current = true;
      // Не включаем спиннер, если имеются роли — избегаем визуального мигания
      setState(prev => ({ ...prev, loading: prev.roles.length === 0, error: null }));

      // Получаем Telegram ID из sessionStorage или WebApp
      const getTelegramId = () => {
        const storedId = sessionStorage.getItem('tg_id');
        if (storedId) return storedId;
        
        if (typeof window !== 'undefined' && (window as any).Telegram?.WebApp) {
          const wa = (window as any).Telegram.WebApp;
          const webAppUser = wa?.initDataUnsafe?.user;
          const uidUnsafe = webAppUser?.id?.toString();
          if (uidUnsafe) return uidUnsafe;
          // Фоллбек: парсим initData (querystring), достаём user.id
          try {
            const initDataStr = typeof wa?.initData === 'string' ? wa.initData : '';
            if (initDataStr && initDataStr.length) {
              const params = new URLSearchParams(initDataStr);
              const userJson = params.get('user');
              if (userJson) {
                const userObj = JSON.parse(userJson);
                const parsedId = userObj?.id;
                if (parsedId) {
                  try { sessionStorage.setItem('tg_id', String(parsedId)); } catch {}
                  return String(parsedId);
                }
              }
            }
          } catch {}
        }
        // Попытка извлечь tg_id из JWT payload и синхронизация
        try {
          const tok = sessionStorage.getItem('token') || localStorage.getItem('token');
          if (tok) {
            const parts = tok.split('.');
            if (parts.length >= 2) {
              const pad = (s: string) => s + '='.repeat((4 - (s.length % 4)) % 4);
              const b64 = pad(parts[1].replace(/-/g, '+').replace(/_/g, '/'));
              const json = typeof atob === 'function' ? decodeURIComponent(Array.prototype.map.call(atob(b64), (c: string) => '%'+('00'+c.charCodeAt(0).toString(16)).slice(-2)).join('')) : '';
              if (json) {
                const payload = JSON.parse(json);
                const claim = String(payload.tg_id || payload.sub || '');
                if (claim) {
                  try { sessionStorage.setItem('tg_id', claim); } catch {}
                  return claim;
                }
              }
            }
          }
        } catch {}
        return null;
      };

      const telegramId = getTelegramId();

      // Единый фасад, единые заголовки: стабильность и одинаковое поведение кэша/базового URL
      const data = await api<any>('/user-management/my-permissions', { method: 'GET', signal: controllerRef.current.signal as any });

      // Нормализуем ответ обеих схем
      let roles = (data.roles || []).map((r: any) => ({ id: r.id, name: r.name, description: r.description }));
      // Склейка с sticky, чтобы не деградировать роль в рамках сессии
      roles = mergeWithSticky(roles);
      // Выставляем глобальный флаг BYPASS при повышенных ролях
      setBypassGuardFlag(roles);
      const permissions = Array.isArray(data.permissions) ? data.permissions : [];
      // Кэшируем успешный ответ, чтобы переживать кратковременные ошибки/перезагрузки
      try {
        sessionStorage.setItem('sp_roles_cache', JSON.stringify({ roles, permissions }));
        sessionStorage.setItem('sp_roles_cache_at', String(Date.now()));
      } catch {}
      // Обновляем sticky при наличии повышенных ролей
      persistStickyIfElevated(roles);
      // Синхронизируем tg_id из ролей-ответа, если сервер его вложил в токен и FE ещё не имеет
      try {
        if (!sessionStorage.getItem('tg_id')) {
          const token = (sessionStorage.getItem('token') || localStorage.getItem('token')) || '';
          const parts = token.split('.');
          if (parts.length >= 2) {
            const pad = (s: string) => s + '='.repeat((4 - (s.length % 4)) % 4);
            const b64 = pad(parts[1].replace(/-/g, '+').replace(/_/g, '/'));
            const json = typeof atob === 'function' ? decodeURIComponent(Array.prototype.map.call(atob(b64), (c: string) => '%'+('00'+c.charCodeAt(0).toString(16)).slice(-2)).join('')) : '';
            if (json) {
              const payload = JSON.parse(json);
              const claimTg = String(payload.tg_id || payload.sub || '');
              if (claimTg) sessionStorage.setItem('tg_id', claimTg);
            }
          }
        }
      } catch {}
      // Пропускаем, если после нас стартовал другой запрос
      if (mySeq !== seqRef.current) return;
      const nextKey = rolesToKey(roles);
      const prevKey = lastRolesKeyRef.current;
      lastRolesKeyRef.current = nextKey;
      // Обновляем состояние только если состав ролей действительно изменился
      const normalizedRoles: UserRole[] = roles.map((r: any) => ({ id: Number(r.id), name: String(r.name), description: r.description, is_system: Boolean((r as any)?.is_system ?? false) }));
      setState((prev: PermissionsState): PermissionsState => (nextKey !== prevKey ? { roles: normalizedRoles, permissions, limits: {}, loading: false, error: null } : { ...prev, loading: false, error: null }));
    } catch (error) {
      // Аборт предыдущего запроса — это нормальный сценарий, не считаем ошибкой
      try {
        const name = (error as any)?.name || '';
        const msg = (error as any)?.message || '';
        if (String(name).includes('AbortError') || String(msg).toLowerCase().includes('aborted')) {
          return;
        }
      } catch {}
      console.error('Ошибка загрузки полномочий:', error);
      // Пытаемся восстановить из кэша, не сбрасывая роли до "start"
      try {
        const raw = sessionStorage.getItem('sp_roles_cache');
        if (raw) {
          const parsed = JSON.parse(raw || '{}');
          const roles = (Array.isArray(parsed.roles) ? parsed.roles : []).map((r:any)=>({ id:Number(r.id), name:String(r.name), description:r.description, is_system:Boolean(r?.is_system??false) })) as UserRole[];
          const permissions = Array.isArray(parsed.permissions) ? parsed.permissions : [];
          // Склейка с sticky
          const merged = mergeWithSticky(roles).map((r:any)=>({ id:Number(r.id), name:String(r.name), description:r.description, is_system:Boolean(r?.is_system??false) })) as UserRole[];
        // Синхронизация флага BYPASS для кэшированного/слияного набора
        setBypassGuardFlag(merged);
          lastRolesKeyRef.current = rolesToKey(merged);
          setState((prev: PermissionsState): PermissionsState => ({ ...prev, roles: merged, permissions, loading: false, error: null }));
          return;
        }
      } catch {}
      setState(prev => ({ ...prev, loading: false, error: error instanceof Error ? error.message : 'Неизвестная ошибка' }));
    }
    finally {
      inFlightRef.current = false;
    }
  };

  // Проверка наличия конкретного права
  const hasPermission = (permission: string): boolean => {
    return state.permissions.includes(permission);
  };

  // Проверка наличия роли
  const hasRole = (roleName: string): boolean => {
    return state.roles.some(role => role.name === roleName);
  };

  // Проверка лимитов
  const checkLimits = (action: string): boolean => {
    // Здесь можно добавить логику проверки лимитов
    // Например, для daily_requests, max_tokens и т.д.
    return true;
  };

  // Обновление полномочий
  const refreshPermissions = async () => {
    await fetchPermissions();
  };

  useEffect(() => {
    // Стартовая попытка
    const getId = () => {
      try {
        return sessionStorage.getItem('tg_id') || (window as any).Telegram?.WebApp?.initDataUnsafe?.user?.id?.toString() || null;
      } catch { return null; }
    };
    const id0 = getId();
    const hasToken = (() => { try { return !!(sessionStorage.getItem('token') || localStorage.getItem('token')); } catch { return false; } })();
    // Пытаемся восстановить роли из кэша немедленно, чтобы не мигать "start"
    try {
      const raw = sessionStorage.getItem('sp_roles_cache');
      const atRaw = sessionStorage.getItem('sp_roles_cache_at');
      const cacheTtlMs = 5 * 60 * 1000;
      const isFresh = atRaw ? (Date.now() - Number(atRaw)) < cacheTtlMs : false;
      if (raw) {
        const parsed = JSON.parse(raw || '{}');
        let roles = Array.isArray(parsed.roles) ? parsed.roles : [];
        roles = mergeWithSticky(roles);
        // Мгновенно выставляем флаг BYPASS для исключения мерцаний до сетевого ответа
        setBypassGuardFlag(roles);
        const permissions = Array.isArray(parsed.permissions) ? parsed.permissions : [];
        if (roles.length > 0 || permissions.length > 0) {
          lastRolesKeyRef.current = rolesToKey(roles);
          setState(prev => ({ ...prev, roles, permissions, loading: !isFresh }));
          // Если кэш свежий — не включаем спиннер вообще
        }
      }
    } catch {}
    // Даже без tg_id и токена пробуем загрузить полномочия: сервер аутентифицирует по HttpOnly cookie (sp_web/sp_token)
    fetchPermissions();

    // Авто‑обновление при появлении tg_id позже (например, после раннего init Telegram)
    let timer: any = null;
    let tries = 0;
    const poll = async () => {
      try {
        const id = getId();
        if (id) {
          await fetchPermissions();
          return; // прекращаем поллинг
        }
        // Если id нет, но есть initData — попробуем бэкенд‑авторизацию (без хардкода)
        const ok = await ensureBackendAuth();
        if (ok) {
          await fetchPermissions();
          return;
        }
      } catch {}
      if (++tries < 20) { // до ~10 секунд при шаге 500мс
        timer = setTimeout(poll, 500);
      }
    };
    if (!id0 && !hasToken) {
      timer = setTimeout(poll, 500);
    }
    const onAuth = () => { try { fetchPermissions(); } catch {} };
    const onWebCookie = () => { try { fetchPermissions(); } catch {} };
    try { window.addEventListener('sp:auth', onAuth as any); } catch {}
    try { window.addEventListener('sp:webcookie', onWebCookie as any); } catch {}
    return () => { 
      if (timer) try { clearTimeout(timer); } catch {}
      try { window.removeEventListener('sp:auth', onAuth as any); } catch {}
      try { window.removeEventListener('sp:webcookie', onWebCookie as any); } catch {}
    };
  }, []);

  return (
    <PermissionsContext.Provider
      value={{
        state,
        hasPermission,
        hasRole,
        checkLimits,
        refreshPermissions,
      }}
    >
      {children}
    </PermissionsContext.Provider>
  );
};

// Хук для использования системы полномочий
export const usePermissions = () => {
  const context = useContext(PermissionsContext);
  if (!context) {
    throw new Error('usePermissions должен использоваться внутри PermissionsProvider');
  }
  return context;
};

// Компонент для условного рендеринга на основе полномочий
export const PermissionGate: React.FC<{
  permission?: string;
  role?: string;
  fallback?: React.ReactNode;
  children: React.ReactNode;
}> = ({ permission, role, fallback = null, children }) => {
  const { hasPermission, hasRole } = usePermissions();

  const hasAccess = () => {
    if (permission && !hasPermission(permission)) return false;
    if (role && !hasRole(role)) return false;
    return true;
  };

  return hasAccess() ? <>{children}</> : <>{fallback}</>;
};

// Хук для определения платформы (веб или мини-апп)
export const usePlatform = () => {
  const [platform, setPlatform] = useState<'web' | 'miniapp' | 'unknown'>('unknown');

  useEffect(() => {
    const detectPlatform = () => {
      // Проверяем наличие Telegram WebApp
      const isTelegramWebApp = typeof window !== 'undefined' && (
        ((window as any).Telegram && (window as any).Telegram.WebApp) ||
        window.location.hostname.includes('t.me') ||
        window.location.hostname.includes('telegram.org') ||
        document.body.classList.contains('telegram-mini-app')
      );

      if (isTelegramWebApp) {
        setPlatform('miniapp');
      } else {
        setPlatform('web');
      }
    };

    detectPlatform();
  }, []);

  return {
    platform,
    isMiniApp: platform === 'miniapp',
    isWeb: platform === 'web',
  };
};

// Компонент для условного рендеринга на основе платформы
export const PlatformGate: React.FC<{
  platform: 'web' | 'miniapp';
  children: React.ReactNode;
  fallback?: React.ReactNode;
}> = ({ platform: targetPlatform, children, fallback = null }) => {
  const { platform } = usePlatform();
  
  return platform === targetPlatform ? <>{children}</> : <>{fallback}</>;
};
