import React from 'react'
import { createRoot } from 'react-dom/client'
import App from './App'
// Ленивая загрузка — только второстепенные компоненты; MiniShell грузим синхронно для стабильности
const ModernHeader = React.lazy(() => import('./components/ModernHeader'));
const TelegramHome = React.lazy(() => import('./pages/TelegramHome'));
const MiniAppChat = React.lazy(() => import('./pages/MiniAppChat'));
const Prompts = React.lazy(() => import('./pages/Prompts'));
import MiniShell from './mini/MiniShell';
import { MemoryRouter, Routes, Route } from 'react-router-dom';
import { PermissionsProvider } from './hooks/usePermissions';
import { ConfigProvider } from 'antd';
import { useTheme } from './hooks/useTheme';
import StartScreen from './components/StartScreen'
// Упрощено: удалены эксперименты DirectHome/BootDiag и лишние импорты
// CSS импорты перенесены в App.tsx для правильного порядка

class RootErrorBoundary extends React.Component<React.PropsWithChildren, { hasError: boolean; error?: any; info?: any }>{
  constructor(props:any){
    super(props);
    this.state = { hasError: false };
  }
  static getDerivedStateFromError(error:any){
    return { hasError: true, error };
  }
  componentDidCatch(error:any, info:any){
    // Логируем максимум деталей в консоль, чтобы понять причину белого экрана
    // Не используем внешние репортеры
    // eslint-disable-next-line no-console
    console.error('[ROOT] Uncaught render error:', error, info);
    this.setState({ info });
  }
  render(){
    if (this.state.hasError){
      // Единовременный ретрай на React invariant #300/#310 (слишком много ререндеров/invalid hook)
      try {
        const msg = String(this.state.error?.message || this.state.error || '');
        const isReactInvariant = (
          msg.includes('Minified React error #') ||
          msg.includes('invariant=300') ||
          msg.includes('invariant=310')
        );
        const tried = (() => { try { return sessionStorage.getItem('sp_react_retry'); } catch { return null; } })();
        if (isReactInvariant && !tried) {
          try { sessionStorage.setItem('sp_react_retry', '1'); } catch {}
          try { const u = new URL(window.location.href); u.searchParams.set('_r', Date.now().toString()); window.location.replace(u.toString()); } catch {}
          return null as any;
        }
      } catch {}
      try {
        const msg = String(this.state.error?.message || this.state.error || '');
        const isChunkErr = (
          msg.includes('ChunkLoadError') ||
          msg.includes('Loading chunk') ||
          msg.includes('Failed to fetch dynamically imported module')
        );
        const tried = (() => { try { return sessionStorage.getItem('sp_root_retry'); } catch { return null; } })();
        if (isChunkErr && !tried) {
          try { sessionStorage.setItem('sp_root_retry', '1'); } catch {}
          try { const u = new URL(window.location.href); u.searchParams.set('_r', Date.now().toString()); window.location.replace(u.toString()); } catch {}
          return null as any;
        }
      } catch {}
      // Продакшн‑экран: краткое сообщение без подробностей, детали в консоли
      try {
        // eslint-disable-next-line no-console
        console.error('[ROOT] Uncaught render error:', this.state.error, this.state.info);
      } catch {}
  // DIAG: включаем показ стека по параметру ?diag=1, а в MiniApp — принудительно
  const diag = (() => {
    try {
      const usp = new URLSearchParams((typeof window !== 'undefined' && window.location.search) || '');
      if (usp.get('diag') === '1') return true;
      const isTg = !!(window as any).Telegram?.WebApp;
      return isTg ? true : false;
    } catch { return false; }
  })();
      const details = (() => { try { return String(this.state.error?.stack || this.state.error || ''); } catch { return ''; } })();
      const comp = (() => { try { return String((this.state.info as any)?.componentStack || ''); } catch { return ''; } })();
      return (
        <div style={{padding:16, fontFamily:'ui-sans-serif, system-ui', background:'#0f172a', color:'#e5e7eb', minHeight:'100vh', display:'flex', alignItems:'center', justifyContent:'center'}}>
          <div style={{background:'#111827', border:'1px solid rgba(31,41,55,0.45)', borderRadius:12, padding:16, maxWidth:560, width:'100%', textAlign:'center'}}>
            <div style={{fontWeight:600, marginBottom:8}}>Произошла ошибка интерфейса</div>
            <div style={{fontSize:13, opacity:0.85}}>Пожалуйста, обновите мини‑приложение. Если проблема повторяется — пришлите скрин в поддержку.</div>
            <div style={{height:12}} />
            <button onClick={()=>{try{ sessionStorage.removeItem('sp_root_retry'); sessionStorage.removeItem('sp_react_retry'); const u=new URL(window.location.href); u.searchParams.set('_r', Date.now().toString()); window.location.replace(u.toString()); }catch{ try{ window.location.reload(); }catch{} }}} style={{background:'#3B82F6', color:'#fff', border:'none', borderRadius:8, padding:'8px 12px', cursor:'pointer'}}>Обновить</button>
            {diag ? (
              <div style={{textAlign:'left', marginTop:12}}>
                {/* React runtime diagnostics */}
                <div style={{display:'flex', alignItems:'center', justifyContent:'space-between', gap:8}}>
                  <div style={{fontSize:12, color:'#9CA3AF'}}>DIAG: react</div>
                </div>
                <pre style={{whiteSpace:'pre-wrap', fontSize:11, background:'#0b1220', padding:8, borderRadius:6, border:'1px solid rgba(31,41,55,0.45)', userSelect:'text'}}>{(() => {
                  try {
                    const v = (React as any).version;
                    const rsize = (window as any).__REACT_DEVTOOLS_GLOBAL_HOOK__?.renderers?.size;
                    return `[ReactCheck] version=${String(v||'unknown')} renderers=${String(rsize||'n/a')}`;
                  } catch (e:any) { return 'ReactCheck error: '+ String(e?.message||e); }
                })()}</pre>
                <div style={{display:'flex', alignItems:'center', justifyContent:'space-between', gap:8}}>
                  <div style={{fontSize:12, color:'#9CA3AF'}}>DIAG: stack</div>
                  <button
                    onClick={() => {
                      try {
                        const text = `STACK\n${details}\n\nCOMPONENT\n${comp}`;
                        const fallbackCopy = (t:string) => {
                          try {
                            const ta = document.createElement('textarea');
                            ta.value = t;
                            ta.style.position = 'fixed';
                            ta.style.left = '-9999px';
                            ta.style.top = '0';
                            ta.setAttribute('readonly', '');
                            document.body.appendChild(ta);
                            ta.select();
                            document.execCommand('copy');
                            document.body.removeChild(ta);
                          } catch {}
                        };
                        // В WebView Telegram navigator.clipboard может быть недоступен — пробуем fallback первым
                        fallbackCopy(text);
                        // Затем пробуем официальное API, если доступно (не мешает уже скопированному)
                        try { (navigator as any).clipboard?.writeText?.(text).catch(()=>{}); } catch {}
                      } catch {}
                    }}
                    style={{background:'transparent', color:'#9CA3AF', border:'1px solid #334155', borderRadius:6, padding:'6px 10px', cursor:'pointer', fontSize:12}}
                    title="Скопировать детали"
                  >
                    Скопировать
                  </button>
                </div>
                <pre style={{whiteSpace:'pre-wrap', fontSize:11, background:'#0b1220', padding:8, borderRadius:6, border:'1px solid rgba(31,41,55,0.45)', userSelect:'text', maxHeight:'42vh', overflow:'auto'}}>{details.substring(0, 4000)}</pre>
                {comp ? (
                  <>
                    <div style={{fontSize:12, color:'#9CA3AF', margin:'8px 0 6px'}}>componentStack</div>
                    <pre style={{whiteSpace:'pre-wrap', fontSize:11, background:'#0b1220', padding:8, borderRadius:6, border:'1px solid rgba(31,41,55,0.45)', userSelect:'text', maxHeight:'32vh', overflow:'auto'}}>{comp.substring(0, 2000)}</pre>
                  </>
                ) : null}
              </div>
            ) : null}
          </div>
        </div>
      );
    }
    return this.props.children as any;
  }
}

function ensureRootElement(): HTMLElement {
  try {
    const el = document.getElementById('root');
    if (el) return el;
  } catch {}
  const created = document.createElement('div');
  created.id = 'root';
  document.body.appendChild(created);
  return created;
}

const rootEl = ensureRootElement();
// Сигнал готовности для снятия FOUC
try { document.documentElement.classList.add('sp-ready'); } catch {}

// Убраны флаги __SP_FLAGS__/SAFE_BOOT/DIAG/NOREACT — единый путь рендера
const DIAG = false;
const NOREACT = false;
const FORCE_HOME = false;

// Грубый защитный cache-bust при обновлении фронтенда (устранение залипания старой версии в WebView)
try {
  const BUILD_VER = '2025-09-30-rbac-webcookie-v1';
  const usp = new URLSearchParams((typeof window !== 'undefined' && window.location.search) || '');
  const curVer = usp.get('_v') || '';
  const stored = (typeof window !== 'undefined') ? window.localStorage?.getItem('sp_build_ver') : null;
  if (curVer !== BUILD_VER && stored !== BUILD_VER) {
    try { window.localStorage?.setItem('sp_build_ver', BUILD_VER); } catch {}
    const u = new URL(window.location.href);
    u.searchParams.set('_v', BUILD_VER);
    window.location.replace(u.toString());
  }
} catch {}

// Предварительный безопасный бут: до появления tg_id / валидного токена рендерим только StartScreen
const Boot: React.FC = () => {
  const [starting, setStarting] = React.useState(false);
  const [authTick, setAuthTick] = React.useState(0);
  const [envProbeDone, setEnvProbeDone] = React.useState(false);
  const hasToken = (() => { try { return !!(sessionStorage.getItem('token') || localStorage.getItem('token')); } catch { return false; } })();
  const hasTgId = (() => { try { return !!sessionStorage.getItem('tg_id'); } catch { return false; } })();
  const wa: any = (window as any).Telegram?.WebApp;
  const isWa = !!wa;
  // Короткая задержка определения окружения, чтобы избежать мигания до загрузки SDK
  React.useEffect(() => {
    const t = setTimeout(() => { try { setEnvProbeDone(true); } catch {} }, 450);
    return () => { try { clearTimeout(t); } catch {} };
  }, []);
  // Поллинг появления tg_id выполняем на верхнем уровне, без нарушения правил хуков
  React.useEffect(() => {
    if (!(isWa && !hasToken && !hasTgId)) return;
    let timer: any = null;
    let tries = 0;
    const check = () => {
      try {
        const waId = (window as any).Telegram?.WebApp?.initDataUnsafe?.user?.id;
        const sid = (() => { try { return sessionStorage.getItem('tg_id'); } catch { return null; } })();
        if (waId && !sid) { try { sessionStorage.setItem('tg_id', String(waId)); } catch {} }
        if (waId || sid) { setAuthTick(t => t + 1); return; }
      } catch {}
      if (++tries < 40) { timer = setTimeout(check, 500); }
    };
    check();
    return () => { if (timer) try { clearTimeout(timer); } catch {} };
  }, [isWa, hasToken, hasTgId]);
  // MiniApp: всегда используем стабильный MiniShell (обход падения #310 в App)
  if (isWa) {
    return <MiniShell />;
  }
  // Web: полный App только при наличии токена или tg_id
  const canRunApp = hasToken || hasTgId;
  if (!canRunApp) {
    // В первые ~450мс показываем нейтральный спиннер, чтобы избежать мигания в MiniApp
    if (!isWa && !envProbeDone) {
      return <div className="screen loading"><div className="spinner" /></div>;
    }
    return <StartScreen onStart={() => { try { setStarting(true); wa?.ready?.(); wa?.expand?.(); } catch {}; }} starting={starting} />;
  }
  return (
    <App />
  );
};

const root = createRoot(rootEl);
// Рантайм‑проверка единственности React/ReactDOM для диагностики #310
try {
  const reactA = (React as any).version;
  const reactB = (window as any).__REACT_DEVTOOLS_GLOBAL_HOOK__?.renderers?.size;
  // eslint-disable-next-line no-console
  console.log('[ReactCheck] version=', reactA, ' renderers=', reactB);
} catch {}
root.render(
  <RootErrorBoundary>
    <Boot />
  </RootErrorBoundary>
);
